#include "Managers/HorizonMatchesManager.h"
void UHorizonMatchesManager::RequestMatches(const FString& UserId){GetMatches(UserId,FOnMatchesComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonMyMatches& V,const FString& Code,const FString& Message){OnMatchesResult.Broadcast(Ok,V,Code,Message);}));}
void UHorizonMatchesManager::RequestMatchLimits(const FString& UserId){GetLimits(UserId,FOnMatchLimitsComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonMatchLimitsView& V,const FString& Code,const FString& Message){OnMatchLimitsResult.Broadcast(Ok,V,Code,Message);}));}
void UHorizonMatchesManager::RequestOpenMatches(const FString& UserId, int64 MinStrength, int64 MaxStrength, int32 Limit, const FString& Cursor){FindOpenMatches(UserId,MinStrength,MaxStrength,FOnOpenMatchesComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonMatchPage& V,const FString& Code,const FString& Message){OnOpenMatchesResult.Broadcast(Ok,V,Code,Message);}),Limit,Cursor);}
void UHorizonMatchesManager::RequestMatch(const FString& UserId, const FString& MatchId){GetMatch(UserId,MatchId,FOnMatchComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonMatchRead& V,const FString& Code,const FString& Message){OnMatchReadResult.Broadcast(Ok,V,Code,Message);}));}
