void UHorizonMatchesManager::AdvanceMatchTimeout(const FString& UserId, const FString& MatchId, int64 ExpectedRevision){AdvanceTimeout(UserId,MatchId,ExpectedRevision,FOnMatchComplete::CreateWeakLambda(this,[this](bool Ok,const FHorizonMatchRead& V,const FString& Code,const FString& Message){OnMatchReadResult.Broadcast(Ok,V,Code,Message);}));}
